={{ JSON.stringify((() => {
  const config = $('Lead Discovery Config & Parameters').first()?.json || {};
  const norm = $('Normalize Inputs').first()?.json || {};
  const ind = config.industry || norm.industry || 'Local Business';
  const loc = config.location || norm.location || 'Honolulu, Hawaii';
  const count = Math.min(15, Math.max(1, config.lead_count || norm.lead_count || 10));

  const userPrompt = [
    'You are Kent, expert local lead scout for Zumify. Search Google for real, active local businesses for industry "' + ind + '" in "' + loc + '".',
    'Find ' + count + ' real, existing companies with active websites currently operating in "' + loc + '".',
    'For each business, extract:',
    '- "name": exact registered business name',
    '- "domain": clean website hostname directly from Google search citations (e.g. company.com, no http/www/slashes)',
    '- "website": full authentic website URL',
    '- "phone": public phone number',
    '- "email": verified public inquiry email address if published on their site, otherwise null',
    '- "reviews": Google star rating and review count (e.g. "4.8 stars (85 Google reviews)")',
    '- "growth": summary of services, recent projects, or business scale',
    '',
    'CRITICAL ANTI-HALLUCINATION RULES FOR DOMAINS & URLS:',
    '- Every website MUST be an authentic official domain that appears in your Google Search result citations.',
    '- NEVER fabricate, guess, or synthesize domain names by combining the business name with city names (e.g. do NOT invent "[businessname]honolulu.com" or "[businessname]hawaii.com").',
    '- If you cannot confirm an official website from Google search results, set "website": null and "domain": null.',
    '- STRICT REQUIREMENT: Output valid JSON only, a JSON array of objects with the keys specified above.'
  ].join('\n');

  return {
    contents: [
      {
        role: 'user',
        parts: [{ text: userPrompt }]
      }
    ],
    tools: [
      { google_search: {} }
    ]
  };
})()) }}

