={{ JSON.stringify((() => {
  const item = $('Merge Discovery Context').first()?.json || {};
  const candidates = item.candidates || [];
  const industry = item.industry || 'Construction';
  const location = item.location || 'Honolulu, Hawaii';

  // Audit up to 8 benchmark cohort candidates starting from Rank #1
  const auditCohort = candidates.slice(0, 8);
  const candidatesList = auditCohort.map((c, i) => (i + 1) + '. [Search Rank ' + (c.search_rank || ('#' + (i+1))) + '] ' + c.business + ' (' + c.website + ') - Email: ' + (c.contact_email || 'No email detected') + ' - SEO Gap: ' + (c.seo_gap_summary || 'Needs local keyword and technical optimization')).join('\n');

  const sysText = "You are Kent, expert Technical Web Auditor for Zumify (Hawaii). We offer web and SEO services, auditing top local businesses starting from Rank #1 downward to evaluate technical performance, conversion readiness, and search dominance. In this node, you inspect candidate websites and evaluate how well each website is doing specifically in terms of: OUTDATED WEBSITES. Always return valid JSON with clean ASCII text (no unicode en-dashes, no emojis).";

  const userText = [
    "TECHNICAL AUDIT METRIC 1/12: OUTDATED WEBSITES",
    "",
    "TARGET BUSINESS WEBSITES (STARTING FROM RANK #1 IN " + location.toUpperCase() + " " + industry.toUpperCase() + "):",
    candidatesList,
    "",
    "AUDIT DIRECTIVE (HOW WELL IS THE WEBSITE DOING):",
    "Evaluate candidate websites specifically on how well they perform for 'OUTDATED WEBSITES'.",
    "Evaluate exclusively how visually and architecturally outdated the websites are (look for 2010-2016 design aesthetic, fixed-width layouts, dated copyright years, obsolete textures/gradients, visual clutter).",
    "",
    "RATING & SCORING GUIDELINES:",
    "- 'how_well_doing': Rate as 'Doing Well' (modern standard), 'Needs Optimization' (moderate flaws), or 'Poor / Failing' (severe flaws/unusable)",
    "- 'metric_score': Score 0 to 10 (10 = doing exceptionally well, 0-4 = failing / critical vulnerability)",
    "- 'is_flagged': boolean (true if problematic or represents a Zumify SEO/web upgrade opportunity)",
    "- 'severity': 'Critical' | 'High' | 'Moderate' | 'Clean'",
    "- 'findings': Detailed technical observation explaining how well or poorly the website is doing on this metric",
    "",
    "OUTPUT REQUIREMENT (STRICT JSON ONLY):",
    "Return a JSON object with a 'results' array where each object has:",
    "- 'business': string (business name)",
    "- 'website': string (website domain)",
    "- 'how_well_doing': 'Doing Well' | 'Needs Optimization' | 'Poor / Failing'",
    "- 'metric_score': number (0-10)",
    "- 'is_flagged': boolean",
    "- 'severity': 'Critical' | 'High' | 'Moderate' | 'Clean'",
    "- 'findings': string"
  ].join('\n');

  return {
    model: $('Select Model').item.json.model || 'gemma4:26b',
    messages: [
      { role: 'system', content: sysText },
      { role: 'user', content: userText }
    ],
    format: 'json',
    stream: false,
    options: {
      temperature: $('Select Model').item.json.temperature || 0.3
    }
  };
})()) }}

